+      filters: {
+        type: "object",
+        additionalProperties: false,
+        properties: {
+          include_domains: {
+            type: "array",
+            items: { type: "string" },
+            description: "Optional list of domains to include.",
+          },
+          exclude_domains: {
+            type: "array",
+            items: { type: "string" },
+            description: "Optional list of domains to exclude.",
+          },
+        },
+      },
