+    return true;
+  });
+
+  if (!toolNames.has(NINEROUTER_WEB_SEARCH_FALLBACK_TOOL_NAME)) {
+    preservedTools.unshift(buildFallbackTool(toRecord(builtInSearchTools[0]), options.sourceFormat));
+  }

